import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source code (inline extension)
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void swish_forward_kernel(const scalar_t* __restrict__ input,
                                     scalar_t* __restrict__ output,
                                     int64_t N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int64_t i = idx; i < N; i += stride) {
        // Load half, convert to float for computation
        float x = __half2float(input[i]);
        float sigmoid = 1.0f / (1.0f + expf(-x));
        float y = x * sigmoid;
        output[i] = __float2half(y);
    }
}

template <typename scalar_t>
__global__ void swish_backward_kernel(const scalar_t* __restrict__ input,
                                      const scalar_t* __restrict__ grad_output,
                                      scalar_t* __restrict__ grad_input,
                                      int64_t N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int64_t i = idx; i < N; i += stride) {
        float x = __half2float(input[i]);
        float g_out = __half2float(grad_output[i]);
        float sigmoid = 1.0f / (1.0f + expf(-x));
        // derivative of swish: sigmoid + x * sigmoid * (1 - sigmoid)
        float grad = sigmoid + x * sigmoid * (1.0f - sigmoid);
        float g = g_out * grad;
        grad_input[i] = __float2half(g);
    }
}

// C++ interface
torch::Tensor swish_forward(torch::Tensor input) {
    auto output = torch::empty_like(input, torch::MemoryFormat::Contiguous);
    const int64_t N = input.numel();

    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "swish_forward_kernel", ([&] {
        swish_forward_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N);
    }));
    cudaGetLastError(); // for debugging
    return output;
}

torch::Tensor swish_backward(torch::Tensor input,
                             torch::Tensor grad_output) {
    auto grad_input = torch::empty_like(input, torch::MemoryFormat::Contiguous);
    const int64_t N = input.numel();

    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "swish_backward_kernel", ([&] {
        swish_backward_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            grad_output.data_ptr<scalar_t>(),
            grad_input.data_ptr<scalar_t>(),
            N);
    }));
    cudaGetLastError();
    return grad_input;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &swish_forward, "Swish forward (fp16)");
    m.def("backward", &swish_backward, "Swish backward (fp16)");
}
'''

# ----------------------------------------------------------------------
# Build the extension
# ----------------------------------------------------------------------
module = load_inline(name='swish_ext',
                     cpp_sources='',
                     cuda_sources=cuda_source,
                     functions=['forward', 'backward'],
                     verbose=False)

# ----------------------------------------------------------------------
# Autograd Function wrapping the CUDA kernels
# ----------------------------------------------------------------------
class SwishFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input):
        ctx.save_for_backward(input)
        return module.forward(input)

    @staticmethod
    def backward(ctx, grad_output):
        (input,) = ctx.saved_tensors
        grad_input = module.backward(input, grad_output)
        return grad_input

# ----------------------------------------------------------------------
# Model using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return SwishFunction.apply(x)

# ----------------------------------------------------------------------
# Helper functions matching the reference API
# ----------------------------------------------------------------------
def get_inputs():
    x = torch.rand(4096, 393216, device='cuda', dtype=torch.float16)
    return [x]

def get_init_inputs():
    return []  # No special initialization inputs needed
